177	```ts
178	/* Pure data helpers for the property dashboard — bucketing, growth, collection
179	   rate, and the per-property filter. All figures exclude voided invoices. */
180	
181	export type Timeframe = 'day' | 'week' | 'month' | 'year';
182	export interface Bucket { label: string; valueCents: number }
183	
184	const isPaid = (i: any) => i.status === 'paid' || i.status === 'paid_external';
185	const notVoided = (invs: any[]) => invs.filter((i: any) => i.status !== 'voided');
186	const paidAt = (i: any) => new Date(i.paidAt ?? i.createdAt);
187	const sumCents = (invs: any[]) => invs.reduce((s: number, i: any) => s + (i.amountCents ?? 0), 0);
188	const inWin = (d: Date, s: Date, e: Date) => d >= s && d < e;
189	
190	/* Current + previous window for a timeframe. Week is Monday-start; month/year
191	   are calendar periods; day is a rolling 24h. */
192	export function periodWindow(tf: Timeframe, now = new Date()) {
193	  if (tf === 'day') {
194	    const start = new Date(now.getTime() - 24 * 3600000);
195	    return { start, end: now, prevStart: new Date(now.getTime() - 48 * 3600000), prevEnd: start };
196	  }
197	  if (tf === 'week') {
198	    const d = new Date(now); d.setHours(0, 0, 0, 0);
199	    const start = new Date(d); start.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // Monday
200	    const prevStart = new Date(start); prevStart.setDate(start.getDate() - 7);
201	    return { start, end: now, prevStart, prevEnd: start };
202	  }
203	  if (tf === 'month') {
204	    const start = new Date(now.getFullYear(), now.getMonth(), 1);
205	    return { start, end: now, prevStart: new Date(now.getFullYear(), now.getMonth() - 1, 1), prevEnd: start };
206	  }
207	  const start = new Date(now.getFullYear(), 0, 1);
208	  return { start, end: now, prevStart: new Date(now.getFullYear() - 1, 0, 1), prevEnd: start };
209	}
210	
211	/* Rent collected (paid invoices, by paid date) inside [start, end). */
212	export function collectedCents(invoices: any[], start: Date, end: Date): number {
213	  return sumCents(notVoided(invoices).filter(isPaid).filter((i: any) => inWin(paidAt(i), start, end)));
214	}
215	
216	/* % change vs previous period; null when there's no previous baseline. */
217	export function growthPct(current: number, previous: number): number | null {
218	  if (previous <= 0) return null;
219	  return Math.round(((current - previous) / previous) * 100);
220	}
221	
222	/* paid ÷ non-voided invoices SENT (createdAt) in the window, as a rounded %. */
223	export function collectionRate(invoices: any[], start: Date, end: Date): number | null {
224	  const sent = notVoided(invoices).filter((i: any) => inWin(new Date(i.createdAt), start, end));
225	  if (sent.length === 0) return null;
226	  return Math.round((sent.filter(isPaid).length / sent.length) * 100);
227	}
228	
229	/* Calendar buckets of collected rent for the bar chart.
230	   day = 8×3h blocks · week = M-start 7 days · month = W1..W4/5 · year = J..D */
231	export function buildBuckets(invoices: any[], tf: Timeframe, now = new Date()): Bucket[] {
232	  const paid = notVoided(invoices).filter(isPaid);
233	  const bucket = (s: Date, e: Date, label: string): Bucket =>
234	    ({ label, valueCents: sumCents(paid.filter((i: any) => inWin(paidAt(i), s, e))) });
235	
236	  if (tf === 'day') {
237	    // End of the current 3-hour block, then 8 blocks backwards.
238	    const end = new Date(now); end.setMinutes(0, 0, 0);
239	    end.setHours(end.getHours() - (end.getHours() % 3) + 3);
240	    return Array.from({ length: 8 }, (_, k) => {
241	      const s = new Date(end.getTime() - (8 - k) * 3 * 3600000);
242	      const e = new Date(end.getTime() - (7 - k) * 3 * 3600000);
243	      const h = s.getHours();
244	      const label = h === 0 ? '12a' : h < 12 ? `${h}a` : h === 12 ? '12p' : `${h - 12}p`;
245	      return bucket(s, e, label);
246	    });
247	  }
248	  if (tf === 'week') {
249	    const { start } = periodWindow('week', now);
250	    return ['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((label, d) => {
251	      const s = new Date(start); s.setDate(start.getDate() + d);
252	      const e = new Date(start); e.setDate(start.getDate() + d + 1);
253	      return bucket(s, e, label);
254	    });
255	  }
256	  if (tf === 'month') {
257	    const first = new Date(now.getFullYear(), now.getMonth(), 1);
258	    const days = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
259	    return Array.from({ length: Math.ceil(days / 7) }, (_, w) => {
260	      const s = new Date(first); s.setDate(1 + w * 7);
261	      const e = new Date(first); e.setDate(1 + (w + 1) * 7);
262	      return bucket(s, e, `W${w + 1}`);
263	    });
264	  }
265	  return ['J', 'F', 'M', 'A', 'M', 'J', 'J', 'A', 'S', 'O', 'N', 'D'].map((label, m) =>
266	    bucket(new Date(now.getFullYear(), m, 1), new Date(now.getFullYear(), m + 1, 1), label));
267	}
268	
269	/* Portfolio filter. addr=null → everything. Invoices missing propertyAddress
270	   fall back to their tenant's address via tenantProfileId. */
271	export function filterByProperty(invoices: any[], tenants: any[], addr: string | null) {
272	  if (!addr) return { invoices, tenants };
273	  const byId = new Map(tenants.map((t: any) => [t.id, t]));
274	  return {
275	    invoices: invoices.filter((i: any) =>
276	      (i.propertyAddress ?? byId.get(i.tenantProfileId)?.propertyAddress) === addr),
277	    tenants: tenants.filter((t: any) => t.propertyAddress === addr),
278	  };
279	}
280	
281	/* Mockup-style compact money: $980 under 1k, 2.5k / 12k above. */
282	export function fmtCompact(cents: number): string {
283	  const d = cents / 100;
284	  if (d >= 1000) {
285	    const k = d / 1000;
286	    return `${k >= 10 ? Math.round(k) : Math.round(k * 10) / 10}k`;
287	  }
288	  return `$${Math.round(d)}`;
289	}
290	```
