582	### Task 3: RentBarChart — clickable animated SVG bars with value pill
583	
584	**Files:**
585	- Modify: `client/src/pages/property/property-dashboard.tsx`
586	
587	**Interfaces:**
588	- Consumes: `Bucket`, `fmtCompact` from Task 1; `buckets`, `selectedIdx`, `setSelBar`, `tf` state from Task 2.
589	- Produces: `RentBarChart({ buckets, selectedIdx, onSelectBar, animKey })` rendered in the hero chart slot.
590	
591	**Animation approach:** Always render `MAX_SLOTS = 12` `<rect>`s. Slots `< buckets.length` are positioned by the current bucket-count layout; slots `>=` count keep their last x but collapse height to 0 at the baseline. CSS transitions on `x`/`y`/`width`/`height` (SVG2 geometry properties — supported in the Chromium/WebKit webviews this app targets) make existing bars slide/re-space, entering bars grow from the baseline, and leaving bars sink back into it. First mount grows all bars from 0 via a `reveal` flag.
592	
593	- [ ] **Step 1: Add the component**
594	
595	In `client/src/pages/property/property-dashboard.tsx`, add above `export default`:
596	
597	```tsx
598	/* ── Bar chart — clickable, animates between timeframes ── */
599	const MAX_SLOTS = 12;
600	
601	function RentBarChart({ buckets, selectedIdx, onSelectBar, animKey }: {
602	  buckets: { label: string; valueCents: number }[];
603	  selectedIdx: number;
604	  onSelectBar: (i: number) => void;
605	  animKey: string;
606	}) {
607	  const W = 375, CH = 190, LABEL_H = 30, H = CH + LABEL_H, PADX = 10, BASE = CH;
608	  const n = buckets.length;
609	  const gap = n > 8 ? 8 : 14;
610	  const bw = (W - PADX * 2 - gap * (n - 1)) / n;
611	  const x = (i: number) => PADX + i * (bw + gap);
612	
613	  const [reveal, setReveal] = useState(false);
614	  useEffect(() => { const t = setTimeout(() => setReveal(true), 60); return () => clearTimeout(t); }, []);
615	
616	  const maxVal = Math.max(...buckets.map(b => b.valueCents), 1);
617	  const hOf = (v: number) => v <= 0 ? 6 : 12 + (v / maxVal) * (CH - 40);
618	
619	  const sel = buckets[selectedIdx];
620	  const selX = x(Math.min(selectedIdx, n - 1)) + bw / 2;
621	  const selTop = BASE - hOf(sel?.valueCents ?? 0);
622	
623	  return (
624	    <div style={{ position: 'relative', margin: '22px -6px 0' }}>
625	      <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: 'block', height: 'auto', overflow: 'visible' }}>
626	        {Array.from({ length: MAX_SLOTS }, (_, i) => {
627	          const active = i < n;
628	          const bh = active && reveal ? hOf(buckets[i].valueCents) : 0;
629	          const bx = active ? x(i) : W - PADX - bw;
630	          return (
631	            <rect key={i} className="pd-bar"
632	              x={bx} width={Math.max(bw, 1)}
633	              y={BASE - bh} height={bh}
634	              rx={Math.min(7, bw / 2.4)}
635	              fill={i === selectedIdx ? SEL : BAR}
636	              style={{ cursor: active ? 'pointer' : 'default', pointerEvents: active ? 'auto' : 'none' }}
637	              onClick={() => active && onSelectBar(i)}
638	            />
639	          );
640	        })}
641	        {buckets.map((b, i) => (
642	          <text key={`${animKey}-${i}`} className="pd-bar-label"
643	            x={x(i) + bw / 2} y={CH + 22} textAnchor="middle"
644	            fontFamily="Outfit, system-ui" fontWeight="600" fontSize={n > 8 ? 11 : 13} fill={SKY}>
645	            {b.label}
646	          </text>
647	        ))}
648	      </svg>
649	      {/* Value pill above the selected bar */}
650	      {sel && (
651	        <div key={`${animKey}-${selectedIdx}`} className="pd-bar-pill"
652	          style={{ position: 'absolute', left: `${(selX / W) * 100}%`, top: `${(selTop / H) * 100}%`, transform: 'translate(-50%, calc(-100% - 8px))', background: SEL, color: NAVY, padding: '5px 14px', borderRadius: 999, fontWeight: 700, fontSize: 13, whiteSpace: 'nowrap', boxShadow: '0 6px 16px rgba(88,171,255,0.35)', pointerEvents: 'none' }}>
653	          {fmtCompact(sel.valueCents)}
654	        </div>
655	      )}
656	    </div>
657	  );
658	}
659	```
