const go = (next: string, dir = 'up') => {
  if (next === 'home') {
    triggerConveyor(screen, dir);
    setScreen('home');
    setSelectedTenant(null);
    setAmount(0);
    setFrequency('once');
    setSplitMode(false);
    setPendingDest(null);
    setAmountDest('send');
    setChargeType(null);
    setChargeLabel('');
    setDueSel(7);
    setChargeDocUrl(null);
    setChargeDocName('');
    return;
  }
  // Send/External with no tenant: remember destination, go to tenant picker
  if ((next === 'send' || next === 'external') && !selectedTenant) {
    setPendingDest(next as 'send' | 'external');
    if (screen === 'home') triggerConveyor(screen, 'up');
    setContentKey(k => k + 1);
    setScreen('tenants');
    return;
  }
  if (screen === 'home') triggerConveyor(screen, dir);
  setContentKey(k => k + 1);
  setScreen(next);
};

const handleTenantSelect = (t: any, preAmount: number) => {
  setSelectedTenant(t);
  setContentKey(k => k + 1);
  // Go to the screen the user originally intended (send / external / bill), default send
  const dest = pendingDest || 'send';
  setPendingDest(null);
  if (dest === 'bill') {
    // A charge is a fresh amount — start at the keypad, then land on the bill configurator.
    setChargeType(null); setChargeLabel(''); setDueSel(7); setAmount(0);
    setChargeDocUrl(null); setChargeDocName('');
    setAmountDest('bill');
    setScreen('amount');
    return;
  }
  setAmount(preAmount);

